G=load(); print(sorted(G))
def f(gi):
    cnt=Counter(x for r in gi for x in r)
    bgc=cnt.most_common(1)[0][0]
    rest=[c for c,_ in cnt.most_common() if c!=bgc]
    rest.sort(key=lambda c:-cnt[c])
    bar,noise=rest[0],rest[1]
    H,W=len(gi),len(gi[0])
    bcells=[(r,c) for r in range(H) for c in range(W) if gi[r][c]==bar]
    bycol={}
    for r,c in bcells: bycol.setdefault(c,[]).append(r)
    spans=[(c,sorted(rows)) for c,rows in bycol.items()]
    def span_containing_row(row):
        for c,sp in spans:
            if min(sp)<=row<=max(sp): return sp
        return None
    out=[[gi[r][c] for c in range(W)] for r in range(H)]
    fills=set()
    for nr,nc in [(r,c) for r in range(H) for c in range(W) if gi[r][c]==noise]:
        sp=span_containing_row(nr)
        if sp: fills.add(nr-sp[0])
        for x in range(W):
            if gi[nr][x]!=bar: out[nr][x]=noise
        out[nr][nc]=4
    for fr in fills:
        for c in range(W):
            if gi[fr][c]!=bar: out[fr][c]=noise
    return out
for name in ['Demo pair 5','Demo pair 6']:
    print(name,'match:',f(G[name+' input'])==G[name+' output'])
